CREATE OR REPLACE VIEW "sxc_out"."v_rule_disjunction" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT CAST(t."parent_id" AS text) AS "parent_id", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (CAST(t."child_id" AS text) IS NOT NULL) AND ((t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(E'8642.75' AS numeric), CAST(E'13.579' AS numeric))) OR ((EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE CAST(n."part_id" AS text) = CAST(t."child_id" AS text) AND (CAST(n."unit" AS text) IS NOT NULL AND CAST(n."unit" AS text) IN (CAST(E'DRPMARK-pc' AS text), CAST(E'DRPMARK-box' AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" >= CAST(E'0.4321' AS numeric))) OR (t."line_id" IS NULL)) GROUP BY CAST(t."parent_id" AS text), t."qty_per") r;

