WITH "sxc_ex_bom_line"("child_id", "qty_per", "line_id", "parent_id") AS (VALUES (CAST(:p1 AS bpchar(12)), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS integer), CAST(:p4 AS bpchar(12))), (CAST(:p5 AS bpchar(12)), CAST(:p6 AS numeric(18,6)), CAST(:p7 AS integer), CAST(:p8 AS bpchar(12)))), "sxc_ex_part"("part_id", "unit") AS (VALUES (CAST(:p9 AS bpchar(12)), CAST(:p10 AS bpchar(12)))) SELECT * FROM (SELECT CAST(t."parent_id" AS text) AS "parent_id", t."qty_per", count(*) AS "n" FROM "sxc_ex_bom_line" t WHERE (CAST(t."child_id" AS text) IS NOT NULL) AND ((t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(:p11 AS numeric), CAST(:p12 AS numeric))) OR ((EXISTS (SELECT 1 FROM "sxc_ex_part" n WHERE CAST(n."part_id" AS text) = CAST(t."child_id" AS text) AND (CAST(n."unit" AS text) IS NOT NULL AND CAST(n."unit" AS text) IN (CAST(:p13 AS text), CAST(:p14 AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" >= CAST(:p15 AS numeric))) OR (t."line_id" IS NULL)) GROUP BY CAST(t."parent_id" AS text), t."qty_per") r;

-- rule edge_distinct (row): parameterized; p1 numeric
