-- rule same_name_components: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_same_name_components" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT DISTINCT d."parent_id" FROM (SELECT CAST(t."parent_id" AS text) AS "parent_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" nc ON CAST(nc."part_id" AS text) = CAST(t."child_id" AS text) WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(nc."name" AS text) IS NOT NULL GROUP BY CAST(t."parent_id" AS text), CAST(nc."name" AS text) HAVING count(DISTINCT CAST(t."child_id" AS text)) >= CAST(E'2' AS bigint)) d WHERE d."parent_id" IS NOT NULL) r;

-- example same_name_components[0]: parameterized; 23 parameters
WITH "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p1 AS bpchar(12)), CAST(:p2 AS bpchar(12))), (CAST(:p3 AS bpchar(12)), CAST(:p4 AS bpchar(12))), (CAST(:p5 AS bpchar(12)), CAST(:p6 AS bpchar(12))), (CAST(:p7 AS bpchar(12)), CAST(:p8 AS bpchar(12))), (CAST(:p9 AS bpchar(12)), CAST(:p10 AS bpchar(12))), (CAST(:p11 AS bpchar(12)), CAST(:p12 AS bpchar(12))), (CAST(:p13 AS bpchar(12)), CAST(:p14 AS bpchar(12))), (CAST(:p15 AS bpchar(12)), CAST(:p16 AS bpchar(12)))), "sxc_ex_part"("part_id", "name") AS (VALUES (CAST(:p17 AS bpchar(12)), CAST(:p18 AS bpchar(24))), (CAST(:p19 AS bpchar(12)), CAST(:p20 AS bpchar(24))), (CAST(:p21 AS bpchar(12)), CAST(:p22 AS bpchar(24)))) SELECT * FROM (SELECT DISTINCT d."parent_id" FROM (SELECT CAST(t."parent_id" AS text) AS "parent_id" FROM "sxc_ex_bom_line" t JOIN "sxc_ex_part" nc ON CAST(nc."part_id" AS text) = CAST(t."child_id" AS text) WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(nc."name" AS text) IS NOT NULL GROUP BY CAST(t."parent_id" AS text), CAST(nc."name" AS text) HAVING count(DISTINCT CAST(t."child_id" AS text)) >= CAST(:p23 AS bigint)) d WHERE d."parent_id" IS NOT NULL) r;

-- rule odd_quantity (mode_outlier): parameterized; p1 bigint, p2 numeric, p3 numeric, p4 numeric
WITH g AS (SELECT CAST(t."child_id" AS text) AS grp, count(*) AS n_rows, count(DISTINCT CAST(t."parent_id" AS text)) AS n_distinct FROM "sxc_rules"."bom_line" t WHERE CAST(t."child_id" AS text) IS NOT NULL GROUP BY CAST(t."child_id" AS text)), f AS (SELECT CAST(t."child_id" AS text) AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE CAST(t."child_id" AS text) IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY CAST(t."child_id" AS text), t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(:p1 AS bigint) AND f.n_val * CAST(:p2 AS numeric) >= CAST(:p3 AS numeric) * g.n_rows AND f.val > 0) SELECT CAST(t."parent_id" AS text) AS "parent_id", CAST(t."child_id" AS text) AS "child_id", t."qty_per", m.mode_value AS "mode", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = CAST(t."child_id" AS text) WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(:p4 AS numeric) * m.mode_value OR CAST(:p4 AS numeric) * t."qty_per" <= m.mode_value) GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text), t."qty_per", m.mode_value;

-- rule odd_quantity: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_odd_quantity" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."child_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."mode" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (WITH g AS (SELECT CAST(t."child_id" AS text) AS grp, count(*) AS n_rows, count(DISTINCT CAST(t."parent_id" AS text)) AS n_distinct FROM "sxc_rules"."bom_line" t WHERE CAST(t."child_id" AS text) IS NOT NULL GROUP BY CAST(t."child_id" AS text)), f AS (SELECT CAST(t."child_id" AS text) AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE CAST(t."child_id" AS text) IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY CAST(t."child_id" AS text), t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(E'3' AS bigint) AND f.n_val * CAST(E'4' AS numeric) >= CAST(E'3' AS numeric) * g.n_rows AND f.val > 0) SELECT CAST(t."parent_id" AS text) AS "parent_id", CAST(t."child_id" AS text) AS "child_id", t."qty_per", m.mode_value AS "mode", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = CAST(t."child_id" AS text) WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(E'20' AS numeric) * m.mode_value OR CAST(E'20' AS numeric) * t."qty_per" <= m.mode_value) GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text), t."qty_per", m.mode_value) r;

-- example odd_quantity[0]: parameterized; 22 parameters
WITH "sxc_ex_bom_line"("child_id", "qty_per", "parent_id") AS (VALUES (CAST(:p1 AS bpchar(12)), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS bpchar(12))), (CAST(:p4 AS bpchar(12)), CAST(:p5 AS numeric(18,6)), CAST(:p6 AS bpchar(12))), (CAST(:p7 AS bpchar(12)), CAST(:p8 AS numeric(18,6)), CAST(:p9 AS bpchar(12))), (CAST(:p10 AS bpchar(12)), CAST(:p11 AS numeric(18,6)), CAST(:p12 AS bpchar(12))), (CAST(:p13 AS bpchar(12)), CAST(:p14 AS numeric(18,6)), CAST(:p15 AS bpchar(12))), (CAST(:p16 AS bpchar(12)), CAST(:p17 AS numeric(18,6)), CAST(:p18 AS bpchar(12)))) SELECT * FROM (WITH g AS (SELECT CAST(t."child_id" AS text) AS grp, count(*) AS n_rows, count(DISTINCT CAST(t."parent_id" AS text)) AS n_distinct FROM "sxc_ex_bom_line" t WHERE CAST(t."child_id" AS text) IS NOT NULL GROUP BY CAST(t."child_id" AS text)), f AS (SELECT CAST(t."child_id" AS text) AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_ex_bom_line" t WHERE CAST(t."child_id" AS text) IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY CAST(t."child_id" AS text), t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(:p19 AS bigint) AND f.n_val * CAST(:p20 AS numeric) >= CAST(:p21 AS numeric) * g.n_rows AND f.val > 0) SELECT CAST(t."parent_id" AS text) AS "parent_id", CAST(t."child_id" AS text) AS "child_id", t."qty_per", m.mode_value AS "mode", count(*) AS "n" FROM "sxc_ex_bom_line" t JOIN m ON m.grp = CAST(t."child_id" AS text) WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(:p22 AS numeric) * m.mode_value OR CAST(:p22 AS numeric) * t."qty_per" <= m.mode_value) GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text), t."qty_per", m.mode_value) r;

-- rule twin_assemblies (same_signature): parameterized; p1 bigint
WITH e AS (SELECT CAST(t."parent_id" AS text) AS node, CAST(t."child_id" AS text) AS kid, sum(t."qty_per") AS qsum FROM "sxc_rules"."bom_line" t WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(t."child_id" AS text) IS NOT NULL GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text)), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT CAST(n."part_id" AS text) AS member, s.sig, CAST(n."name" AS text) AS a1, CAST(n."unit" AS text) AS a2, CAST(n."part_class" AS text) AS a3 FROM s JOIN "sxc_rules"."part" n ON CAST(n."part_id" AS text) = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1, k.a2, k.a3)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(:p1 AS bigint);

-- rule twin_assemblies: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_twin_assemblies" AS
SELECT r.*, row_number() OVER (ORDER BY r."group_id" COLLATE "C" NULLS FIRST, r."member" COLLATE "C" NULLS FIRST) AS ord FROM (WITH e AS (SELECT CAST(t."parent_id" AS text) AS node, CAST(t."child_id" AS text) AS kid, sum(t."qty_per") AS qsum FROM "sxc_rules"."bom_line" t WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(t."child_id" AS text) IS NOT NULL GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text)), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT CAST(n."part_id" AS text) AS member, s.sig, CAST(n."name" AS text) AS a1, CAST(n."unit" AS text) AS a2, CAST(n."part_class" AS text) AS a3 FROM s JOIN "sxc_rules"."part" n ON CAST(n."part_id" AS text) = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1, k.a2, k.a3)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(E'2' AS bigint)) r;

-- example twin_assemblies[0]: parameterized; 25 parameters
WITH "sxc_ex_part"("part_id", "name", "unit", "part_class") AS (VALUES (CAST(:p1 AS bpchar(12)), CAST(:p2 AS bpchar(24)), CAST(:p3 AS bpchar(12)), CAST(:p4 AS bpchar(12))), (CAST(:p5 AS bpchar(12)), CAST(:p6 AS bpchar(24)), CAST(:p7 AS bpchar(12)), CAST(:p8 AS bpchar(12))), (CAST(:p9 AS bpchar(12)), CAST(:p10 AS bpchar(24)), CAST(:p11 AS bpchar(12)), CAST(:p12 AS bpchar(12)))), "sxc_ex_bom_line"("parent_id", "child_id", "qty_per") AS (VALUES (CAST(:p13 AS bpchar(12)), CAST(:p14 AS bpchar(12)), CAST(:p15 AS numeric(18,6))), (CAST(:p16 AS bpchar(12)), CAST(:p17 AS bpchar(12)), CAST(:p18 AS numeric(18,6))), (CAST(:p19 AS bpchar(12)), CAST(:p20 AS bpchar(12)), CAST(:p21 AS numeric(18,6))), (CAST(:p22 AS bpchar(12)), CAST(:p23 AS bpchar(12)), CAST(:p24 AS numeric(18,6)))) SELECT * FROM (WITH e AS (SELECT CAST(t."parent_id" AS text) AS node, CAST(t."child_id" AS text) AS kid, sum(t."qty_per") AS qsum FROM "sxc_ex_bom_line" t WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(t."child_id" AS text) IS NOT NULL GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text)), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT CAST(n."part_id" AS text) AS member, s.sig, CAST(n."name" AS text) AS a1, CAST(n."unit" AS text) AS a2, CAST(n."part_class" AS text) AS a3 FROM s JOIN "sxc_ex_part" n ON CAST(n."part_id" AS text) = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1, k.a2, k.a3)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(:p25 AS bigint)) r;

-- rule stored_level_drift (stored_metric): parameterized; p1 bigint
WITH RECURSIVE edge AS (SELECT DISTINCT CAST(t."parent_id" AS text) AS p, CAST(t."child_id" AS text) AS c FROM "sxc_rules"."bom_line" t WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(t."child_id" AS text) IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(:p1 AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT CAST(n."part_id" AS text) AS "part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = CAST(n."part_id" AS text)) THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = CAST(n."part_id" AS text)) THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_rules"."part" n LEFT JOIN ht ON ht.node = CAST(n."part_id" AS text) WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0);

-- rule stored_level_drift: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_stored_level_drift" AS
SELECT r.*, row_number() OVER (ORDER BY r."part_id" COLLATE "C" NULLS FIRST, r."kind" COLLATE "C" NULLS FIRST, r."stored" NULLS FIRST, r."height" NULLS FIRST) AS ord FROM (WITH RECURSIVE edge AS (SELECT DISTINCT CAST(t."parent_id" AS text) AS p, CAST(t."child_id" AS text) AS c FROM "sxc_rules"."bom_line" t WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(t."child_id" AS text) IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(E'17' AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT CAST(n."part_id" AS text) AS "part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = CAST(n."part_id" AS text)) THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = CAST(n."part_id" AS text)) THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_rules"."part" n LEFT JOIN ht ON ht.node = CAST(n."part_id" AS text) WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0)) r;

-- example stored_level_drift[0]: parameterized; 15 parameters
WITH "sxc_ex_part"("part_id", "stored_level") AS (VALUES (CAST(:p1 AS bpchar(12)), CAST(:p2 AS integer)), (CAST(:p3 AS bpchar(12)), CAST(:p4 AS integer)), (CAST(:p5 AS bpchar(12)), CAST(:p6 AS integer)), (CAST(:p7 AS bpchar(12)), CAST(:p8 AS integer)), (CAST(:p9 AS bpchar(12)), CAST(:p10 AS integer))), "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p11 AS bpchar(12)), CAST(:p12 AS bpchar(12))), (CAST(:p13 AS bpchar(12)), CAST(:p14 AS bpchar(12)))) SELECT * FROM (WITH RECURSIVE edge AS (SELECT DISTINCT CAST(t."parent_id" AS text) AS p, CAST(t."child_id" AS text) AS c FROM "sxc_ex_bom_line" t WHERE CAST(t."parent_id" AS text) IS NOT NULL AND CAST(t."child_id" AS text) IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(:p15 AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT CAST(n."part_id" AS text) AS "part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = CAST(n."part_id" AS text)) THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = CAST(n."part_id" AS text)) THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_ex_part" n LEFT JOIN ht ON ht.node = CAST(n."part_id" AS text) WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0)) r;

-- rule grams_in_count_unit (text_quantity): parameterized; p1 text, p2 text, p3 text, p4 text, p5 text, p6 numeric
SELECT CAST(t."parent_id" AS text) AS "parent_id", CAST(t."child_id" AS text) AS "child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON CAST(en."part_id" AS text) = CAST(t."child_id" AS text) CROSS JOIN LATERAL (SELECT regexp_match(CAST(en."name" AS text), CAST(:p1 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p2 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p3 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (CAST(en."unit" AS text) IS NOT NULL AND CAST(en."unit" AS text) IN (CAST(:p4 AS text), CAST(:p5 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p6 AS numeric) * x.numerator GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text), t."qty_per", x.numerator, x.divisor;

-- rule grams_in_count_unit: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_grams_in_count_unit" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."child_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."numerator" NULLS FIRST, r."divisor" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT CAST(t."parent_id" AS text) AS "parent_id", CAST(t."child_id" AS text) AS "child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON CAST(en."part_id" AS text) = CAST(t."child_id" AS text) CROSS JOIN LATERAL (SELECT regexp_match(CAST(en."name" AS text), CAST(E'\\[[ \\t\\n\\r\\f\\v]*([0-9.]+)[ \\t\\n\\r\\f\\v]*g[ \\t\\n\\r\\f\\v]*(?:\\/[ \\t\\n\\r\\f\\v]*([0-9]+)[ \\t\\n\\r\\f\\v]*)?\\]' AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(E'^[0-9]+(\\.[0-9]+)?$' AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(E'^[0-9]+$' AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (CAST(en."unit" AS text) IS NOT NULL AND CAST(en."unit" AS text) IN (CAST(E'pc' AS text), CAST(E'box' AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(E'0.001' AS numeric) * x.numerator GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text), t."qty_per", x.numerator, x.divisor) r;

-- example grams_in_count_unit[0]: parameterized; 30 parameters
WITH "sxc_ex_bom_line"("child_id", "qty_per", "parent_id") AS (VALUES (CAST(:p1 AS bpchar(12)), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS bpchar(12))), (CAST(:p4 AS bpchar(12)), CAST(:p5 AS numeric(18,6)), CAST(:p6 AS bpchar(12))), (CAST(:p7 AS bpchar(12)), CAST(:p8 AS numeric(18,6)), CAST(:p9 AS bpchar(12))), (CAST(:p10 AS bpchar(12)), CAST(:p11 AS numeric(18,6)), CAST(:p12 AS bpchar(12)))), "sxc_ex_part"("part_id", "name", "unit") AS (VALUES (CAST(:p13 AS bpchar(12)), CAST(:p14 AS bpchar(24)), CAST(:p15 AS bpchar(12))), (CAST(:p16 AS bpchar(12)), CAST(:p17 AS bpchar(24)), CAST(:p18 AS bpchar(12))), (CAST(:p19 AS bpchar(12)), CAST(:p20 AS bpchar(24)), CAST(:p21 AS bpchar(12))), (CAST(:p22 AS bpchar(12)), CAST(:p23 AS bpchar(24)), CAST(:p24 AS bpchar(12)))) SELECT * FROM (SELECT CAST(t."parent_id" AS text) AS "parent_id", CAST(t."child_id" AS text) AS "child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_ex_bom_line" t JOIN "sxc_ex_part" en ON CAST(en."part_id" AS text) = CAST(t."child_id" AS text) CROSS JOIN LATERAL (SELECT regexp_match(CAST(en."name" AS text), CAST(:p25 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p26 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p27 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (CAST(en."unit" AS text) IS NOT NULL AND CAST(en."unit" AS text) IN (CAST(:p28 AS text), CAST(:p29 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p30 AS numeric) * x.numerator GROUP BY CAST(t."parent_id" AS text), CAST(t."child_id" AS text), t."qty_per", x.numerator, x.divisor) r;

-- subjects view
CREATE OR REPLACE VIEW "sxc_out"."v_rules_subjects" AS
WITH u AS (SELECT v."parent_id" AS subject, CAST(E'qty_over_limit' AS text) AS rule_id, CAST(E'0' AS bigint) AS rule_ord, CAST(E'0' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_qty_over_limit" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'parent_unknown' AS text) AS rule_id, CAST(E'1' AS bigint) AS rule_ord, CAST(E'0' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_parent_unknown" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."part_id" AS subject, CAST(E'kit_without_bom' AS text) AS rule_id, CAST(E'2' AS bigint) AS rule_ord, CAST(E'0' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_kit_without_bom" v WHERE v."part_id" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'retired_child_in_active_parent' AS text) AS rule_id, CAST(E'3' AS bigint) AS rule_ord, CAST(E'0' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_retired_child_in_active_parent" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."part_id" AS subject, CAST(E'all_children_retired' AS text) AS rule_id, CAST(E'4' AS bigint) AS rule_ord, CAST(E'0' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_all_children_retired" v WHERE v."part_id" IS NOT NULL UNION ALL SELECT v."part_id" AS subject, CAST(E'retired_assembly_in_use' AS text) AS rule_id, CAST(E'5' AS bigint) AS rule_ord, CAST(E'0' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_retired_assembly_in_use" v WHERE v."part_id" IS NOT NULL UNION ALL SELECT v."part_id" AS subject, CAST(E'unknown_procure_code' AS text) AS rule_id, CAST(E'6' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_unknown_procure_code" v WHERE v."part_id" IS NOT NULL UNION ALL SELECT v."part_id" AS subject, CAST(E'temporary_name' AS text) AS rule_id, CAST(E'7' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_temporary_name" v WHERE v."part_id" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'truncated_third' AS text) AS rule_id, CAST(E'8' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_truncated_third" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'repeated_line' AS text) AS rule_id, CAST(E'9' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_repeated_line" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'same_name_components' AS text) AS rule_id, CAST(E'10' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_same_name_components" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'odd_quantity' AS text) AS rule_id, CAST(E'11' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_odd_quantity" v WHERE v."parent_id" IS NOT NULL UNION ALL SELECT v."member" AS subject, CAST(E'twin_assemblies' AS text) AS rule_id, CAST(E'12' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_twin_assemblies" v WHERE v."member" IS NOT NULL UNION ALL SELECT v."parent_id" AS subject, CAST(E'grams_in_count_unit' AS text) AS rule_id, CAST(E'14' AS bigint) AS rule_ord, CAST(E'1' AS bigint) AS severity_rank FROM "sxc_out"."v_rule_grams_in_count_unit" v WHERE v."parent_id" IS NOT NULL), d AS (SELECT DISTINCT u.subject, u.rule_id, u.rule_ord, u.severity_rank FROM u), g AS (SELECT d.subject, min(d.severity_rank) AS severity_rank, count(*) AS rule_count, array_agg(d.rule_id ORDER BY d.rule_ord) AS rules FROM d GROUP BY d.subject) SELECT g.subject, CASE g.severity_rank WHEN 0 THEN CAST(E'violation' AS text) ELSE CAST(E'warning' AS text) END AS severity, g.severity_rank, g.rule_count, g.rules, row_number() OVER (ORDER BY g.severity_rank, g.subject COLLATE "C") AS ord FROM g;
